#[derive(Debug)]
struct Rectangle {
    width: u32,
    height: u32,
}

fn area(r: &Rectangle) -> u32 {
    r.width * r.height
}

fn main() {
    let shapes = [Rectangle { width: 30, height: 50 }, Rectangle { width: 20, height: 20 }];
    for r in &shapes {
        println!("{r:?}: area {}", area(r));
    }
}
